import threading
import weakref

class Memo:
    def __init__(self, max_entries=2):
        if type(max_entries) is not int or not 1 <= max_entries <= 8:
            raise ValueError('capacity')
        self.limit = max_entries
        self.guard = threading.Lock()
        self.owners = weakref.WeakKeyDictionary()

    def get(self, owner, key, compute):
        if not isinstance(key, str) or not 1 <= len(key) <= 32:
            raise ValueError('key')
        with self.guard:
            state = self.owners.get(owner)
            if state is None:
                state = {'lock': threading.RLock(), 'values': {}}
                self.owners[owner] = state
        with state['lock']:
            values = state['values']
            if key in values:
                value = values.pop(key)
                values[key] = value
                return value
            value = compute()
            if type(value) is not int:
                raise ValueError('integer result')
            values[key] = value
            while len(values) > self.limit:
                values.pop(next(iter(values)))
            return value
